  await t('the bot thinks for itself: tools are only offered when the words are about them', () => { const h = require('../harness'), names = (q) => h.toolsFor(q).map((x) => x.function.name); assert.deepStrictEqual(names('what is a closure in javascript'), []); assert.deepStrictEqual(names('give me a motivational quote'), []); assert.deepStrictEqual(names('help me write a message to my manager that I will be late').filter((n) => n === 'compose_email' || n === 'open_chrome'), []); assert(names('send an email to maria').includes('compose_email')); assert(!names('open safari').includes('compose_email') && names('open safari').includes('open_app')); assert(!names('finish this ticket and rebase').includes('delegate_to_desktop'), 'the model has no handoff tool'); assert(!names('what is dependency injection').includes('delegate_to_desktop')); });
  await t('Tulai Desktop is never opened or offered by itself: only an explicit "use Tulai Desktop" hands work over', async () => {
    const hp = require('../handoff-policy');
    for (const s of ['use Tulai Desktop to finish this ticket', 'open desktop and finish this ticket', 'ask Tulai Desktop to review my MR', 'ipasa mo sa Desktop ito']) assert(hp.explicit(s), s + ' is an explicit request');
    for (const s of ['finish this ticket and rebase', "don't use Tulai Desktop", 'review the MR of Paolo', 'what should I say in my standup']) assert(!hp.explicit(s), s + ' is not');
    assert.strictEqual(hp.guard({ delegate: 'x' }, 'finish this ticket').via, 'desktop handoff blocked'); assert(/not opened Desktop/.test(hp.guard({ delegate: 'x' }, 'finish this ticket').reply)); assert.strictEqual(hp.guard({ delegate: 'x' }, 'use Tulai Desktop to finish this ticket').delegate, 'x');
    const x = await say('check my email', 'hp1'); assert(x.r && !x.r.delegate && x.r.agent, JSON.stringify(x.r)); // the bot does it with its own agent: Desktop is never opened
    const o = local.offerDesktop('of1', 'finish this ticket', 'That is bigger work.'); assert(!o.offered && !o.delegate && o.agent && o.via === 'coding agent', JSON.stringify(o)); // bigger work runs in the bot's own coding agent: Desktop is never opened
    const y = await say('yes', 'of1'); assert(!y.r || !y.r.delegate, 'a stray "yes" must not open Desktop');
    const q = await say('what should I say in my standup if I have no blockers', 'of3'); assert(!q.r || !q.r.delegate, 'a question about the standup must not open Desktop');
  });
  await t('install: models are downloaded, resumed, verified and never half-written', async () => {
    const { spawnSync } = require('child_process'), crypto = require('crypto'), http = require('http'), os = require('os'), D = fs.mkdtempSync(os.tmpdir() + '/tulai-fetch-'), blob = crypto.randomBytes(3 * 1048576), sha = crypto.createHash('sha256').update(blob).digest('hex');
    const srv = http.createServer((q, r) => { const m = /bytes=(\d+)-/.exec(q.headers.range || ''), from = m ? +m[1] : 0; r.writeHead(m ? 206 : 200, { 'Content-Length': blob.length - from, ...(m ? { 'Content-Range': `bytes ${from}-${blob.length - 1}/${blob.length}` } : {}) }); r.end(blob.subarray(from)); }); await new Promise((r) => srv.listen(0, '127.0.0.1', r)); const port = srv.address().port;
    const mf = (hash) => { const f = D + '/m.json'; fs.writeFileSync(f, JSON.stringify({ dir: D + '/models', models: [{ id: 'x', what: 'test model', file: 'x.bin', url: `http://127.0.0.1:${port}/x.bin`, sha256: hash, bytes: blob.length, required: true }], brew: [] })); return f; };
    const run = (hash, ...args) => new Promise((res) => { const p = require('child_process').spawn(process.execPath, [require('path').join(__dirname, '..', 'scripts', 'fetch-models.js'), ...args], { env: { ...process.env, TULAI_MODELS_MANIFEST: mf(hash) } }); let out = ''; p.stdout.on('data', (c) => (out += c)); p.stderr.on('data', (c) => (out += c)); p.on('close', (status) => res({ status, stdout: out, stderr: '' })); }); // async: the pretend server lives in this very process
    try {
      assert.strictEqual((await run(sha, '--check')).status, 1, 'missing model must fail the check');
      const a1 = await run(sha); assert.strictEqual(a1.status, 0, a1.stdout + a1.stderr); assert(fs.existsSync(D + '/models/x.bin') && !fs.existsSync(D + '/models/x.bin.part'));
      const a2 = await run(sha); assert(/is ready/.test(a2.stdout) && !/↓/.test(a2.stdout), 'second run must not download again');
      fs.rmSync(D + '/models/x.bin'); fs.writeFileSync(D + '/models/x.bin.part', blob.subarray(0, 1048576)); const a3 = await run(sha); assert.strictEqual(a3.status, 0, a3.stdout); assert(/resuming at 1 MB/.test(a3.stdout), 'must resume a half-finished download'); assert.strictEqual(crypto.createHash('sha256').update(fs.readFileSync(D + '/models/x.bin')).digest('hex'), sha);
      fs.rmSync(D + '/models/x.bin'); const bad = await run('0'.repeat(64)); assert.strictEqual(bad.status, 1); assert(!fs.existsSync(D + '/models/x.bin'), 'a wrong file must never be left in place');
    } finally { srv.close(); fs.rmSync(D, { recursive: true, force: true }); }
  });
  await t('a pending question does not trap a new command', async () => { process.env.TULAY_CHROME_DIR = two; await say('open chrome', 'p1'); const x = await say('what time is it', 'p1'); assert(/^It is /.test(x.r.reply)); });
  for (const [q, re] of [['Anong oras na?', /^It is /], ['Buksan mo ang Safari', /Opened Safari/], ['Paki-open ang Viscode', /Visual Studio Code/], ['buksan ang mb-mobile project sa vscode', /mb-mobile in Visual Studio Code/], ['Isara mo ang Safari', /Closed Safari/], ['Hanapin mo ang pizza', /Searching/], ['Lakasan mo ang volume', /Volume up/], ['I-mute mo', /Muted/], ['Salamat po', /./], ['Can you please introduce yourself?', /I am Tulai/], ['hey tulay can you introduce yourself', /I am Tulai/], ['magpakilala ka nga', /I am Tulai/], ['Kumusta ka', /ready to help/]]) await t('tagalog: ' + q, async () => { const x = await say(q, 'f' + Math.random()); assert(x.r && re.test(x.r.reply), 'got ' + (x.r && x.r.reply)); });
  await t('teams: parses the request', () => { const x = local.parseTeams('can you chat Marco in Ascendion Teams'); assert(x && x.who === 'Marco' && /Ascendion/i.test(x.org)); const y = local.parseTeams('message Maria on teams saying see you at 3'); assert(y && y.who === 'Maria' && y.body === 'see you at 3'); assert.strictEqual(local.parseTeams('message John about the report'), null); });
  await t('teams: message without the word saying', () => { const x = local.parseTeams('message eddy neil on teams are you free later'); assert(x && x.who === 'eddy neil' && x.body === 'are you free later', JSON.stringify(x)); const y = local.parseTeams('chat Marco in Ascendion Teams'); assert(y && y.who === 'Marco' && /Ascendion/i.test(y.org) && !y.body); });
  await t('teams: natural English and Taglish sentences', () => { for (const [q, who, body] of [['send ka nga ng message kay Marko sa Teams', 'Marko', ''], ['send a message to Marco on Teams saying hello', 'Marco', 'hello'], ['padalhan mo ng message si Marco sa Teams na may meeting tayo mamaya', 'Marco', 'may meeting tayo mamaya'], ['mag-message ka kay Marko sa teams', 'Marko', ''], ['send ka ng message kay Maria sa Ascendion Teams na pa-review ng PR', 'Maria', 'pa-review ng PR']]) { const x = local.parseTeams(q); assert(x && x.who === who && (x.body || '') === body, q + ' -> ' + JSON.stringify(x)); } assert.strictEqual(local.parseTeams('send ka nga ng message kay Marko'), null, 'no Teams, not for this engine'); });
  await t('teams: asks for the email once, remembers it, opens a chat with the message typed', async () => { process.env.TULAY_CHROME_DIR = one; const a = await say('can you chat Marco in Ascendion Teams saying are you free', 'tm1'); assert(/work email/.test(a.r.reply) && a.dry === ''); const b = await say('marco dot santos at ascendion dot com', 'tm1'); assert(/teams\.microsoft\.com\/l\/chat.*marco\.santos%40ascendion\.com.*message=are%20you%20free/.test(b.dry) && /press Enter/.test(b.r.reply)); const c = await say('chat Marco on teams', 'tm2'); assert(/teams\.microsoft\.com\/l\/chat/.test(c.dry), 'remembered contact'); });
  await t('teams: "just open Teams" works without an email', async () => { process.env.TULAY_CHROME_DIR = one; await say('chat Zed on teams', 'tm3'); const b = await say('just open teams', 'tm3'); assert(/https:\/\/teams\.microsoft\.com\/$/.test(b.dry.trim()) || /teams\.microsoft\.com\/ *$/.test(b.dry), b.dry); });
  await t('auto-learning requires repeated plausible Tulai names', () => { voice.setAliases([]); let got = []; voice._learn(['frosty lay'], (e) => got.push(e)); assert.strictEqual(got.length, 0, 'once is not enough'); voice._learn(['frosty lay', 'frosty lay', 'yes'], (e) => got.push(e)); assert(!got.some((e) => e.alias === 'frosty lay') && !got.some((e) => e.alias === 'yes')); voice._learn(['hey tulai','hey tulai'],e=>got.push(e));assert(got.some(e=>e.alias==='hey tulai')); });
  await t('spoken email addresses', () => { assert.strictEqual(local.extractEmail('john dot smith at gmail dot com'), 'john.smith@gmail.com'); assert.strictEqual(local.extractEmail('x@y.com'), 'x@y.com'); });
